"use client";

import { FileDown } from "lucide-react";
import * as React from "react";
import { toast } from "sonner";

import { apiDownload } from "@/lib/api/client";
import { errorMessage } from "@/lib/api/errors";
import { saveBlob } from "@/lib/download";

import { Button } from "./button";

/** Downloads a PDF generated by the API (invoice, receipt) under the given file name. */
export function PdfDownloadButton({
  path,
  filename,
  scoped = true,
  className,
  children = "Download PDF",
}: {
  path: string;
  filename: string;
  /** Send the active organization (staff); false for the tenant app. */
  scoped?: boolean;
  className?: string;
  children?: React.ReactNode;
}) {
  const [busy, setBusy] = React.useState(false);
  return (
    <Button
      variant="outline"
      className={className}
      loading={busy}
      onClick={async () => {
        setBusy(true);
        try {
          saveBlob(await apiDownload(path, { scoped }), filename);
        } catch (e) {
          toast.error(errorMessage(e));
        } finally {
          setBusy(false);
        }
      }}
    >
      <FileDown /> {children}
    </Button>
  );
}
